@Test
public void testIsInAlphabetValidBase32Chars() {
    Base32 base32 = new Base32();
    // All letters A-Z should be in the Base32 alphabet
    for (char c = 'A'; c <= 'Z'; c++) {
        assertTrue("Expected " + c + " to be in alphabet", base32.isInAlphabet((byte) c));
    }
