@Test
public void testEncodeOneBytePaddingStandard() {
    // 1 byte input -> modulus 1 at EOF -> 2 encoded chars + 2 pads
    byte[] input = new byte[]{(byte) 'M'};
    byte[] encoded = Base64.encodeBase64(input, false, false);
    String result = new String(encoded);
    assertEquals(4, result.length());
    assertTrue(result.endsWith("=="));
}

@Test
public void testEncodeTwoBytesPaddingStandard() {
    // 2 bytes input -> modulus 2 at EOF -> 3 encoded chars + 1 pad
    byte[] input = new byte[]{(byte) 'M', (byte) 'a'};
    byte[] encoded = Base64.encodeBase64(input, false, false);
    String result = new String(encoded);
    assertEquals(4, result.length());
    assertTrue(result.endsWith("="));
}

@Test
public void testDecodeWithPaddingChar() {
