    byte[] input = new byte[]{(byte) 'M'};
    byte[] encoded = Base64.encodeBase64(input, false, true);
    String result = new String(encoded);
    assertFalse(result.contains("="));
}

@Test
public void testToIntegerBytesAligned() {
    // BigInteger whose bitLength % 8 == 0 triggers the startSrc=1 branch
    java.math.BigInteger bi = java.math.BigInteger.valueOf(256); // bitLength = 9, not aligned
    byte[] result = Base64.toIntegerBytes(bi);
    assertNotNull(result);
    assertTrue(result.length > 0);
}

@Test
public void testToIntegerBytesPositive() {
    java.math.BigInteger bi = java.math.BigInteger.valueOf(1);
    byte[] result = Base64.toIntegerBytes(bi);
    assertNotNull(result);
    assertEquals(new java.math.BigInteger(1, result), bi);
}

@Test
public void testDecodeBase64WithWhitespace() {
    // Whitespace should be ignored during decode
    byte[] decoded = Base64.decodeBase64("TW Fu");
    assertArrayEquals("Man".getBytes(), decoded);
}

@Test
public void testEncodeBase64ChunkedLongInput() {
    // Input long enough to produce multiple chunks
    byte[] input = new byte[200];
    for (int i = 0; i < 200; i++) input[i] = (byte)(i % 128);
    byte[] chunked = Base64.encodeBase64Chunked(input);
    byte[] decoded = Base64.decodeBase64(chunked);
    assertArrayEquals(input, decoded);
}

