}

@Test
public void testPopulateMapWithKeyAndValueTransformer() {
    java.util.Map<Integer, String> map = new java.util.HashMap<>();
    java.util.List<String> elements = java.util.Arrays.asList("hi");
    MapUtils.populateMap(map, elements,
        new Transformer<String, Integer>() { public Integer transform(String s) { return s.length(); } },
        new Transformer<String, String>() { public String transform(String s) { return s.toUpperCase(); } }
    );
    assertEquals("HI", map.get(2));
}

