@Test
public void testVerbosePrintNestedMap() {
    java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
    java.io.PrintStream ps = new java.io.PrintStream(baos);
    java.util.Map<String, Object> inner = new java.util.LinkedHashMap<>();
    inner.put("innerKey", "innerValue");
    java.util.Map<String, Object> outer = new java.util.LinkedHashMap<>();
    outer.put("nested", inner);
    MapUtils.verbosePrint(ps, "root", outer);
    String output = baos.toString();
    assertTrue(output.contains("innerKey"));
    assertTrue(output.contains("innerValue"));
}

@Test
public void testDebugPrintSimpleMap() {
    java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
    java.io.PrintStream ps = new java.io.PrintStream(baos);
    java.util.Map<String, Object> map = new java.util.HashMap<>();
    map.put("key", "value");
    MapUtils.debugPrint(ps, "label", map);
    String output = baos.toString();
    assertTrue(output.contains("key"));
    assertTrue(output.contains("value"));
    assertTrue(output.contains("java.lang.String"));
}

@Test
public void testVerbosePrintSelfReferential() {
    java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
    java.io.PrintStream ps = new java.io.PrintStream(baos);
    java.util.Map<String, Object> map = new java.util.HashMap<>();
    map.put("self", map);
    MapUtils.verbosePrint(ps, "root", map);
    String output = baos.toString();
    assertTrue(output.contains("(this Map)"));
}

