    // Without escape set, escape is DISABLED (\ufffe)
    CSVFormat format = CSVFormat.DEFAULT;
    ExtendedBufferedReader reader = new ExtendedBufferedReader(new java.io.StringReader(""));
    Lexer lexer = new Lexer(format, reader);
    assertFalse(lexer.isEscape('\\'));
    assertFalse(lexer.isEscape('"'));
    lexer.close();
}

@Test
public void testNextTokenEncapsulatedEscapeInside() throws Exception {
    CSVFormat format = CSVFormat.DEFAULT.withEscape('\\');
    ExtendedBufferedReader reader = new ExtendedBufferedReader(new java.io.StringReader("\"hel\\nlo\",world"));
    Lexer lexer = new Lexer(format, reader);
    Token token = new Token();
    Token result = lexer.nextToken(token);
    assertEquals(Token.Type.TOKEN, result.type);
    assertEquals("hel\nlo", result.content.toString());
    lexer.close();
}

@Test
public void testNextTokenLastCharIsEOFReturnsEOF() throws Exception {
    // When lastChar is EOF signal at start
    CSVFormat format = CSVFormat.DEFAULT;
    ExtendedBufferedReader reader = new ExtendedBufferedReader(new java.io.StringReader(""));
    Lexer lexer = new Lexer(format, reader);
    Token token = new Token();
    // First read should detect EOF
    Token result = lexer.nextToken(token);
    assertEquals(Token.Type.EOF, result.type);
    lexer.close();
}

