        public FilterResult tail(Node node, int depth) {
            visited.add("tail:" + ((org.jsoup.nodes.Element)node).tagName());
            return FilterResult.CONTINUE;
        }
    };
    FilterResult result = NodeTraversor.filter(filter, root);
    assertEquals(FilterResult.CONTINUE, result);
    // SKIP_CHILDREN on root means child is not visited
    assertFalse(visited.contains("head:p"));
    assertTrue(visited.contains("head:div"));
    assertTrue(visited.contains("tail:div"));
}

